const TD_T=(x,y,t,o={})=>`<text x="${x}" y="${y}" ${TD_F} font-size="${o.fs||24}" font-weight="${o.fw||600}" text-anchor="${o.a||'start'}" fill="${o.fill||'#18213A'}">${t}</text>`;
const TD_L=(x1,y1,x2,y2,col='#5C6577',w=2,ex='')=>`<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${col}" stroke-width="${w}" stroke-linecap="round" ${ex}/>`;
const TD_box=(x,y,w,h,o={})=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${o.r??14}" fill="${o.fill||'#FFFFFF'}" stroke="${o.st||'#CED4DA'}" stroke-width="${o.sw||2}" ${o.ex||''}/>`;
const TD_pts=(f,t0,t1,x0,x1,yc,k,n)=>{let p=[];for(let i=0;i<=n;i++){const t=t0+(t1-t0)*i/n;p.push(`${(x0+(x1-x0)*i/n).toFixed(1)},${(yc-k*f(t)).toFixed(1)}`)}return p};
const TD_curve=(f,t0,t1,x0,x1,yc,k,col,w=4,n=160,ex='')=>`<polyline points="${TD_pts(f,t0,t1,x0,x1,yc,k,n).join(' ')}" fill="none" stroke="${col}" stroke-width="${w}" stroke-linejoin="round" stroke-linecap="round" ${ex}/>`;
const TD_arrow=(x1,y1,x2,y2,col='#18213A',w=3)=>{const a=Math.atan2(y2-y1,x2-x1),h=14;return TD_L(x1,y1,x2-h*.6*Math.cos(a),y2-h*.6*Math.sin(a),col,w)+`<polygon points="${x2},${y2} ${(x2-h*Math.cos(a)+h*.5*Math.sin(a)).toFixed(1)},${(y2-h*Math.sin(a)-h*.5*Math.cos(a)).toFixed(1)} ${(x2-h*Math.cos(a)-h*.5*Math.sin(a)).toFixed(1)},${(y2-h*Math.sin(a)+h*.5*Math.cos(a)).toFixed(1)}" fill="${col}"/>`};
const TD_brk=(x1,x2,y,col,d=10)=>`<polyline points="${x1},${y-d} ${x1},${y} ${x2},${y} ${x2},${y-d}" fill="none" stroke="${col}" stroke-width="3" stroke-linejoin="round"/>`;
const TD_sub=b=>`<tspan baseline-shift="-0.2em" font-size="72%">${b}</tspan>`;
const TD_MUT='#5C6577', TD_GRY='#ADB5BD';
const TD_FS=`f${TD_sub('s')}`, TD_RB=`R${TD_sub('b')}`, TD_TB=`T${TD_sub('b')}`, TD_TF=`T${TD_sub('f')}`;
const TD_sinc=u=>Math.abs(u)<1e-9?1:Math.sin(Math.PI*u)/(Math.PI*u);
/* PSDs per V²Tb, f in multiples of Rb (the table in the notes) */
const TD_nrz=f=>TD_sinc(f)**2, TD_rz=f=>.25*TD_sinc(f/2)**2, TD_ami=f=>.25*TD_sinc(f/2)**2*Math.sin(Math.PI*f)**2, TD_man=f=>TD_sinc(f/2)**2*Math.sin(Math.PI*f/2)**2;
/* half-bit levels of 1 0 1 1 0 (the worked example's dry run) */
